import{_ as s,C as n,o as i,c as d,a2 as r,E as o,j as a,a as l}from"./chunks/framework.BSaF8iZ6.js";const b=JSON.parse('{"title":"Product Management","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/product-management.md","filePath":"catalog/product-management.md","lastUpdated":1789411447000}'),u={name:"catalog/product-management.md"};function c(g,t,h,p,m,f){const e=n("ImagePopup");return i(),d("div",null,[t[0]||(t[0]=r('<h1 id="product-management" tabindex="-1">Product Management <a class="header-anchor" href="#product-management" aria-label="Permalink to &quot;Product Management&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span></div><p>Sellers create and look after their products in the Seller Panel. This page covers the products list, creating a product, and each step of the product form.</p><h2 id="the-products-list" tabindex="-1">The products list <a class="header-anchor" href="#the-products-list" aria-label="Permalink to &quot;The products list&quot;">​</a></h2><p>Go to <strong>Catalog &gt;&gt; Products</strong>. The list shows every product you sell: the ones you created and the catalog products you sell as your own.</p>',5)),o(e,{src:"/images/product-management/products-list.png",alt:"The seller's products list"}),t[1]||(t[1]=r('<p>Each row shows:</p><ul><li>the name, SKU and product number;</li><li>the image, price, stock and listing ID;</li><li>the status (<strong>Active</strong> or <strong>Disable</strong>), the approval badge, the category and the product type;</li><li>the barcode, or <strong>Not Generated</strong>.</li></ul><p>The approval badge is <strong>Draft</strong>, <strong>Waiting For Approval</strong>, <strong>Approved</strong> or <strong>Rejected</strong>. See <a href="./product-approval">Product Approval</a>.</p><ul><li>Use <strong>Search</strong> or <strong>Filter</strong> to find products by name, SKU, status, approval, draft status, type, category, price, product number, ID or barcode value.</li><li>Click the edit arrow to open a product, or the delete icon to remove it.</li><li>Tick products to use <strong>Select Action</strong>: <strong>Delete</strong>, <strong>Generate Barcode</strong> or <strong>Print Barcodes</strong>. See <a href="./product-barcode">Product Barcode</a>.</li></ul><h2 id="add-a-product" tabindex="-1">Add a product <a class="header-anchor" href="#add-a-product" aria-label="Permalink to &quot;Add a product&quot;">​</a></h2><ol><li>Go to <strong>Catalog &gt;&gt; List Your Product</strong>.</li><li>Choose how to add the product: <ul><li><strong>Create New Products</strong> — create a product that isn&#39;t in the store yet.</li><li><strong>Search Products</strong> — sell a product that is already in the store&#39;s catalog. See <a href="./selling-existing-products">Selling Existing Products</a>.</li><li><strong>Bulk Upload</strong> — add many products from a spreadsheet. See <a href="./bulk-upload">Bulk Upload</a>.</li></ul></li></ol>',6)),o(e,{src:"/images/product-management/create-launcher.png",alt:"The List Your Product page with its three options"}),t[2]||(t[2]=r('<p>The store&#39;s settings and your role decide which options you see. You also need a complete profile. If it isn&#39;t, you are sent back with <strong>Please update your profile details</strong>. See <a href="./../seller-panel/manage-profile">Manage Profile</a>.</p><p>If the store has turned off the stepped product form, <strong>List Your Product</strong> is one page instead. Search for a catalog product under <strong>Search Products</strong>, or choose the <strong>Product Type</strong>, <strong>Attribute Family</strong> and <strong>SKU</strong> under <strong>Create New Products</strong> and click <strong>Continue</strong>.</p><h2 id="create-a-new-product" tabindex="-1">Create a new product <a class="header-anchor" href="#create-a-new-product" aria-label="Permalink to &quot;Create a new product&quot;">​</a></h2><ol><li>Click <strong>Create New Products</strong>.</li><li>Under <strong>What kind of product are you selling?</strong>, choose one: <ul><li><strong>Physical Product</strong> — something you ship.</li><li><strong>Digital Download</strong> — a file such as an e-book or software.</li><li><strong>Service or Membership</strong> — something with no shipping, such as a membership.</li><li><strong>Bookable</strong> — something customers reserve for a date or time.</li><li><strong>Bundle</strong> — several products sold together.</li><li><strong>Grouped Products</strong> — a set of related products shown together.</li></ul></li><li>For a physical product, answer <strong>Does this product have variations?</strong>. Choose <strong>Yes</strong> for a product that comes in sizes or colours.</li><li>Choose the attribute family under <strong>Which attribute family does your product belong to?</strong>.</li><li>For a product with variations, tick the attributes that vary under <strong>Which attributes will vary?</strong>.</li><li>Under <strong>What SKU would you like to use?</strong>, enter a unique SKU made of letters and numbers joined by hyphens, for example <code>ut-organic-crew-tee</code>.</li><li>Click <strong>Continue</strong>. The product is created as a draft and its edit page opens.</li></ol>',4)),o(e,{src:"/images/product-management/scratch-funnel.png",alt:"Choosing the kind of product, the attribute family and the SKU"}),t[3]||(t[3]=a("p",null,"You only see the kinds of product the store allows you to sell.",-1)),t[4]||(t[4]=a("h2",{id:"fill-in-the-product-form",tabindex:"-1"},[l("Fill in the product form "),a("a",{class:"header-anchor",href:"#fill-in-the-product-form","aria-label":'Permalink to "Fill in the product form"'},"​")],-1)),o(e,{src:"/images/product-management/edit-general.png",alt:"The General step of the product form"}),t[5]||(t[5]=r('<p>At the top of the page you&#39;ll find:</p><ul><li><strong>Back</strong>, to return to your products.</li><li><strong>Generate content</strong>, to have Generative AI (Magic AI) write the listing. It appears when the store has switched it on for you and, if you are a team member, your role includes <strong>Generate Content With Magic AI</strong>. See <a href="./../generative-ai/generate-product-content">Generate Product Content</a>.</li><li><strong>Preview</strong>, to open the product on the storefront once it is enabled and visible.</li><li><strong>Save as Draft</strong> and <strong>Submit</strong> for a draft, or <strong>Save Product</strong> once it is submitted.</li><li><strong>Listing Completeness</strong>, a bar showing how much of the form is filled in, when the store has <strong>Show Progress Bar</strong> on.</li></ul><p>If your store has more than one channel or language, choose it at the top before you edit the fields marked with a channel or language name.</p><h3 id="the-steps" tabindex="-1">The steps <a class="header-anchor" href="#the-steps" aria-label="Permalink to &quot;The steps&quot;">​</a></h3><p>Usually the form is split into steps. Move between them with the tabs, or with <strong>Previous</strong> and <strong>Next</strong>. A step with a mistake is marked so you can find it. If the store uses the two-column layout for the product&#39;s attribute family, the whole form is on one page instead. The steps come from the product&#39;s attribute family, so yours may differ. With the default family they are:</p><table tabindex="0"><thead><tr><th>Step</th><th>What you fill in</th></tr></thead><tbody><tr><td><strong>General</strong></td><td>SKU, product number, name, URL key, tax category, and options such as colour, size and brand</td></tr><tr><td><strong>Price</strong></td><td>Price, cost, and a special price with its start and end dates</td></tr><tr><td><strong>Description</strong></td><td>Short description and description</td></tr><tr><td><strong>Shipping</strong></td><td>Length, width, height and weight</td></tr><tr><td><strong>Meta Description</strong></td><td>Meta title, keywords and description for search engines</td></tr><tr><td><strong>Settings</strong></td><td><strong>New</strong>, <strong>Featured</strong>, <strong>Visible Individually</strong>, <strong>Status</strong> and <strong>Guest Checkout</strong></td></tr><tr><td><strong>Inventories</strong></td><td><strong>Manage Stock</strong>, and the quantity in each of your inventory sources</td></tr><tr><td><strong>RMA</strong></td><td><strong>Allow RMA</strong> and the return rule for the product</td></tr><tr><td><strong>Barcode</strong></td><td><strong>Barcode Value</strong>. See <a href="./product-barcode">Product Barcode</a>.</td></tr><tr><td><strong>Media</strong></td><td>Images (PNG or JPEG) and videos (MP4, WebM or MKV)</td></tr><tr><td>The product type</td><td>The details for the kind of product, such as variations or bundle items</td></tr><tr><td><strong>Organization</strong></td><td>Channels, categories, and related, up-sell and cross-sell products</td></tr></tbody></table>',6)),o(e,{src:"/images/product-management/edit-price.png",alt:"The Price step of the product form"}),o(e,{src:"/images/product-management/edit-rma.png",alt:"The RMA step of the product form"}),t[6]||(t[6]=r('<p>The store can change how the form looks for each attribute family. See <a href="./product-form-layout">Product Form Layout</a>.</p><h3 id="customer-group-prices" tabindex="-1">Customer group prices <a class="header-anchor" href="#customer-group-prices" aria-label="Permalink to &quot;Customer group prices&quot;">​</a></h3><p>In the <strong>Price</strong> step, click <strong>Add New</strong> under <strong>Customer Group Price</strong> to offer a different price for a customer group or for larger quantities. Choose the <strong>Customer Group</strong>, enter the <strong>Qty</strong>, choose the <strong>Price Type</strong> (<strong>Fixed</strong> or <strong>Discount</strong>), enter the <strong>Price</strong> and click <strong>Save</strong>.</p><h3 id="the-product-type-step" tabindex="-1">The product type step <a class="header-anchor" href="#the-product-type-step" aria-label="Permalink to &quot;The product type step&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kind of product</th><th>Step</th><th>What you add</th></tr></thead><tbody><tr><td>Physical Product with variations</td><td><strong>Variations</strong></td><td>Variants, each with its own name, SKU, price, weight, status, stock and images. Pick the options for each attribute that varies, such as sizes and colours, and a variant is added for every combination.</td></tr><tr><td>Digital Download</td><td><strong>Downloadable Links</strong></td><td>Links with a title, price, download limit and file or URL, and optional samples</td></tr><tr><td>Bundle</td><td><strong>Bundle Items</strong></td><td>Options with their products and default quantities</td></tr><tr><td>Grouped Products</td><td><strong>Group Products</strong></td><td>The products in the group and their default quantities</td></tr><tr><td>Bookable</td><td><strong>Booking Type</strong></td><td>The booking type and its availability</td></tr><tr><td>Physical Product without variations</td><td><strong>Customizable Item</strong></td><td>Options customers can choose or fill in, such as engraving text</td></tr></tbody></table><h3 id="save-the-product" tabindex="-1">Save the product <a class="header-anchor" href="#save-the-product" aria-label="Permalink to &quot;Save the product&quot;">​</a></h3><ul><li>Click <strong>Save as Draft</strong> to finish later, or <strong>Submit</strong> when the product is ready.</li><li>For a product you have already submitted, click <strong>Save Product</strong>.</li></ul><p>You&#39;ll see <strong>Product updated successfully</strong>. See <a href="./product-approval">Product Approval</a> for what happens after you submit.</p><h2 id="delete-a-product" tabindex="-1">Delete a product <a class="header-anchor" href="#delete-a-product" aria-label="Permalink to &quot;Delete a product&quot;">​</a></h2><p>Click the delete icon on the product&#39;s row, or tick several products and use <strong>Select Action &gt;&gt; Delete</strong>. Deleting a product you created removes it from the store. Deleting a catalog product you sell removes only your offer.</p><h2 id="limits-from-your-plan" tabindex="-1">Limits from your plan <a class="header-anchor" href="#limits-from-your-plan" aria-label="Permalink to &quot;Limits from your plan&quot;">​</a></h2><p>If the store uses subscription plans, your plan can limit how many products you list and which kinds you can create. Once you reach the limit, you&#39;ll see <strong>You have reached max limit of … products.</strong> See <a href="./../subscriptions/choosing-a-plan">Choosing a Plan</a>.</p>',12))])}const P=s(u,[["render",c]]);export{b as __pageData,P as default};
